import nock from 'nock'
import { describe, it } from '@jest/globals'
import { FLY_API_HOSTNAME } from '../src/client'
import { createClient } from '../src/main'
import { VolumeResponse } from '../src/lib/volume'

const fly = createClient(process.env.FLY_API_TOKEN || 'test-token')

describe('volume', () => {
  const app_name = 'ctwntjgykzxhfncfwrfo'
  const volume: VolumeResponse = {
    id: 'vol_0vdyzpeqgpzl383v',
    name: 'pgdata',
    state: 'created',
    size_gb: 2,
    region: 'hkg',
    zone: '553e',
    encrypted: true,
    attached_machine_id: null,
    attached_alloc_id: null,
    created_at: '2023-09-06T10:04:03.905Z',
    blocks: 0,
    block_size: 0,
    blocks_free: 0,
    blocks_avail: 0,
    fstype: '',
    host_dedication_key: '',
  }

  it('lists volumes', async () => {
    nock(FLY_API_HOSTNAME)
      .get(`/v1/apps/${app_name}/volumes`)
      .reply(200, [
        {
          ...volume,
          attached_machine_id: '17811953c92e18',
          blocks: 252918,
          block_size: 4096,
          blocks_free: 234544,
          blocks_avail: 217392,
          fstype: 'ext4',
        },
      ])
    const data = await fly.Volume.listVolumes(app_name)
    console.dir(data, { depth: 5 })
  })

  it('gets volume', async () => {
    const volume_id = volume.id
    nock(FLY_API_HOSTNAME)
      .get(`/v1/apps/${app_name}/volumes/${volume_id}`)
      .reply(200, volume)
    const data = await fly.Volume.getVolume({
      app_name,
      volume_id,
    })
    console.dir(data, { depth: 5 })
  })

  it('creates volume', async () => {
    const body = {
      name: 'pgdata',
      region: 'hkg',
      size_gb: 2,
    }
    nock(FLY_API_HOSTNAME)
      .post(`/v1/apps/${app_name}/volumes`, body)
      .reply(200, volume)
    const data = await fly.Volume.createVolume({
      app_name,
      ...body,
    })
    console.dir(data, { depth: 5 })
  })

  it('deletes volume', async () => {
    const volume_id = volume.id
    nock(FLY_API_HOSTNAME)
      .delete(`/v1/apps/${app_name}/volumes/${volume_id}`)
      .reply(200, {
        ...volume,
        state: 'destroyed',
      })
    const data = await fly.Volume.deleteVolume({
      app_name,
      volume_id,
    })
    console.dir(data, { depth: 5 })
  })

  it('forks volume', async () => {
    const body = {
      name: 'forked',
      region: '',
      source_volume_id: volume.id,
    }
    nock(FLY_API_HOSTNAME)
      .post(`/v1/apps/${app_name}/volumes`, body)
      .reply(200, {
        ...volume,
        id: 'vol_5456e1j33p16378r',
        name: 'forked',
        state: 'hydrating',
      })
    const data = await fly.Volume.createVolume({
      app_name,
      ...body,
    })
    console.dir(data, { depth: 5 })
  })

  it('extends volume', async () => {
    const body = { size_gb: 4 }
    const volume_id = volume.id
    nock(FLY_API_HOSTNAME)
      .put(`/v1/apps/${app_name}/volumes/${volume_id}/extend`, body)
      .reply(200, {
        needs_restart: true,
        volume: {
          ...volume,
          ...body,
        },
      })
    const data = await fly.Volume.extendVolume({
      app_name,
      volume_id,
      ...body,
    })
    console.dir(data, { depth: 5 })
  })

  it('lists snapshots', async () => {
    const volume_id = volume.id
    nock(FLY_API_HOSTNAME)
      .get(`/v1/apps/${app_name}/volumes/${volume_id}/snapshots`)
      .reply(200, [])
    const data = await fly.Volume.listSnapshots({
      app_name,
      volume_id,
    })
    console.dir(data, { depth: 5 })
  })
})

import nock from 'nock'
import { describe, it } from '@jest/globals'
import { FLY_API_HOSTNAME } from '../src/client'
import { createClient } from '../src/main'
import { AppResponse, AppStatus } from '../src/lib/app'

const fly = createClient(process.env.FLY_API_TOKEN || 'test-token')

describe('app', () => {
  const app: AppResponse = {
    name: 'fly-app',
    status: AppStatus.deployed,
    organization: {
      name: 'fly-org',
      slug: 'personal',
    },
    ipAddresses: [
      {
        type: 'v4',
        address: '1.1.1.1'
      },
      {
        type: 'v6',
        address: '2001:db8::1'
      }
    ]
  }

  it('lists apps', async () => {
    const org_slug = app.organization.slug
    nock(FLY_API_HOSTNAME)
      .get('/v1/apps')
      .query({ org_slug })
      .reply(200, {
        total_apps: 1,
        apps: [
          {
            name: app.name,
            machine_count: 1,
            network: 'default',
          },
        ],
      })
    const data = await fly.App.listApps(org_slug)
    console.dir(data, { depth: 10 })
  })

  it('get app', async () => {
    const app_name = app.name
    nock(FLY_API_HOSTNAME).get(`/v1/apps/${app_name}`).reply(200, app)
    const data = await fly.App.getApp(app_name)
    console.dir(data, { depth: 10 })
  })

  it('creates app', async () => {
    const body = {
      org_slug: app.organization.slug,
      app_name: app.name,
    }
    nock(FLY_API_HOSTNAME).post('/v1/apps', body).reply(201)
    const data = await fly.App.createApp(body)
    console.dir(data, { depth: 10 })
  })

  it('deletes app', async () => {
    const app_name = app.name
    nock(FLY_API_HOSTNAME).delete(`/v1/apps/${app_name}`).reply(202)
    const data = await fly.App.deleteApp(app_name)
    console.dir(data, { depth: 10 })
  })
})

